                  'reverse': 'i', 'equal': '7', 'few_unique': 'i % 8',
                  'nearly_sorted': 'i', 'organ_pipe': 'i'}[pattern]
    value = {'int': 'value', 'float': 'value * 0.5', 'mixed': 'value',
             'string': "join(['key_', str(value + 1000000)], '')",
